```go
package main

import (
	"log"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
	"github.com/gofiber/fiber/v2/middleware/limiter"
	"github.com/gofiber/fiber/v2/middleware/cors"
	"github.com/gofiber/fiber/v2/middleware/logger"
	"github.com/gofiber/fiber/v2/middleware/requestid"
)

func main() {
	app := fiber.New()

	// Logger
	app.Use(logger.New())

	// Request ID
	app.Use(requestid.New())

	// Limit requests per IP per minute
	app.Use(limiter.New(limiter.Config{
		Max:        100,
		Expiration: time.Minute,
	}))

	// CORS
	app.Use(cors.New())

	// Stream API endpoint
	app.Post("/stream_api", streamAPIHandler)

	// Serve on port 8000
	log.Fatal(app.Listen(":8000"))
}

func streamAPIHandler(c *fiber.Ctx) error {
	prompt := c.Body().String()

	// 模拟流式生成器
	ch := generateStream(prompt)

	go func() {
		for chunk := range ch {
			err := c.Status(200).Stream(func(writer fiber.Streamer) error {
				return writer.Write(chunk)
			})
			if err != nil {
				log.Println("Error streaming:", err)
				break
			}
			time.Sleep(100 * time.Millisecond) // Simulate delay between chunks
		}
	}()

	return nil
}

// 模拟流式生成器
func generateStream(prompt string) <-chan string {
	ch := make(chan string)
	go func() {
		defer close(ch)

		// 模拟生成多个部分
		for i := 0; i < 10; i++ {
			select {
			case ch <- fmt.Sprintf("Generated part %d of %s\n", i+1, prompt):
			case <-time.After(200 * time.Millisecond):
			}
		}
	}()
	return ch
}
